{
  "findings": [
    {
      "check_id": "CKV_AWS_376",
      "title": "Ensure AWS Elastic Load Balancer listener uses TLS/SSL",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The AWS Elastic Load Balancer listener is configured to use HTTP protocol on port 80, which is not secure."
    },
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The ALB protocol is set to HTTP, which is not secure."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-2016-08\"\n  certificate_arn   = \"arn:aws:acm:REGION:ACCOUNT_ID:certificate/CERTIFICATE_ID\"\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Updated the AWS Elastic Load Balancer listener to use HTTPS protocol on port 443 with a specified SSL policy and certificate ARN."
}
